//! The lookup tables the waveshaping and FM engines read, generated by our
//! own code from the formulas in Mutable Instruments'
//! `plaits/resources/lookup_tables.py` (MIT, Copyright 2016 Emilie Gillet).
//! The Hermite interpolation is ported from Mutable Instruments'
//! `stmlib/dsp/dsp.h` (MIT, Copyright 2012 Emilie Gillet). See
//! THIRD_PARTY_NOTICES.md.
//!
//! They are built once, in `f64`, the first time a macro oscillator is
//! built on the control thread ([`force`]); the audio thread only reads
//! them.

use std::f64::consts::PI;
use std::sync::LazyLock;

/// Half a waveshaper curve's steps: a curve spans -1..1 in twice this.
const SHAPER_HALF: usize = 128;
/// Entries in a waveshaper curve.
pub(super) const SHAPER_SIZE: usize = 2 * SHAPER_HALF + 1;
/// Steps across a wavefolder table's input range of -1..1.
pub(super) const FOLD_STEPS: usize = 512;
/// Entries in a wavefolder table: one before and two after the range, for
/// Hermite interpolation.
const FOLD_SIZE: usize = FOLD_STEPS + 4;
/// Steps across the FM ratio table (one per 1/128 of `harmonics`).
pub(super) const RATIO_STEPS: usize = 128;

pub(super) struct Tables {
    /// The waveshaper curves `harmonics` morphs between, each odd about the
    /// middle: inverse tangent, inverse sine, linear, bump, double bump.
    pub shapers: [[f32; SHAPER_SIZE]; 5],
    /// A smooth sine-folding curve.
    pub fold: [f32; FOLD_SIZE],
    /// A model of an analog five-stage wavefolder.
    pub fold_2: [f32; FOLD_SIZE],
    /// Modulator-to-carrier intervals in semitones, with a flat plateau at
    /// each musically useful ratio.
    pub fm_ratios: [f32; RATIO_STEPS + 2],
}

static TABLES: LazyLock<Tables> = LazyLock::new(build);

/// The tables, built on first use.
pub(super) fn tables() -> &'static Tables {
    &TABLES
}

/// Builds the tables now, so the audio thread never does.
pub(super) fn force() {
    LazyLock::force(&TABLES);
}

fn build() -> Tables {
    Tables {
        shapers: [
            shaper(inverse_tan),
            shaper(|x| (1.0 - 2.0 * x).acos() / PI),
            shaper(|x| x),
            shaper(bump),
            shaper(|x| (PI * x * 1.5).sin()),
        ],
        fold: sine_fold(&fold_inputs()).map(|v| v as f32),
        fold_2: analog_fold(&fold_inputs()).map(|v| v as f32),
        fm_ratios: fm_ratios(),
    }
}

/// A curve from `f` over 0..1, mirrored to an odd curve over -1..1.
fn shaper(f: impl Fn(f64) -> f64) -> [f32; SHAPER_SIZE] {
    let mut table = [0.0; SHAPER_SIZE];
    for (i, entry) in table.iter_mut().enumerate() {
        let (sign, step) = if i < SHAPER_HALF {
            (-1.0, SHAPER_HALF - i)
        } else {
            (1.0, i - SHAPER_HALF)
        };
        *entry = (sign * f(step as f64 / SHAPER_HALF as f64)) as f32;
    }
    table
}

fn inverse_tan(x: f64) -> f64 {
    let scale = 8.0f64.atan();
    ((scale * (1.0 - 2.0 * x)).tan() / 8.0)
        .clamp(-1.0, 1.0)
        .acos()
        / PI
}

fn bump(x: f64) -> f64 {
    let fade_crop = (4.0 - 4.0 * x).min(1.0);
    (1.0 - (PI * x * 1.5).cos()) * (1.0 - (PI * fade_crop).cos()) / 4.5
}

/// The input value at each wavefolder table entry: -1 at index 0, one
/// step per `2 / FOLD_STEPS`, with the last entry repeating the one before.
fn fold_inputs() -> [f64; FOLD_SIZE] {
    let mut x = [0.0; FOLD_SIZE];
    for (i, v) in x.iter_mut().enumerate() {
        *v = i.min(FOLD_SIZE - 2) as f64 / (FOLD_STEPS as f64 / 2.0) - 1.0;
    }
    x
}

/// A sine that folds four times across the range near the middle, easing
/// into a gentle arctangent toward the edges; peak-normalised.
fn sine_fold(x: &[f64; FOLD_SIZE]) -> [f64; FOLD_SIZE] {
    let raw = x.map(|x| {
        let window = (-x * x * 4.0).exp().powi(2);
        (8.0 * PI * x).sin() * window + (3.0 * x).atan() * (1.0 - window)
    });
    let peak = raw.iter().fold(0.0f64, |m, v| m.max(v.abs()));
    raw.map(|v| v / peak)
}

/// An inverting op-amp stage that saturates at `v_sat`, summed through
/// its input and load resistors.
fn deadband(v_in: f64, r_in: f64, r_load: f64) -> f64 {
    const R_FB: f64 = 150.0e3;
    const V_SAT: f64 = 10.47;
    let v_out = (-R_FB / r_in * v_in).clamp(-V_SAT, V_SAT);
    (v_in * R_FB * r_load + v_out * r_in * r_load) / (R_FB * r_load + r_in * r_load + r_in * R_FB)
}

/// Five saturating stages summed and soft-clipped by a diode pair, as in
/// an analog wavefolder; normalised so its highest output is 1.
fn analog_fold(x: &[f64; FOLD_SIZE]) -> [f64; FOLD_SIZE] {
    let raw = x.map(|x| {
        let v_in = x * 12.0;
        let stage_1 = deadband(v_in, 10e3, 100e3);
        let stage_2 = deadband(v_in, 49.9e3, 44.2e3);
        let stage_3 = deadband(v_in, 91e3, 18e3);
        let stage_4 = deadband(v_in, 30e3, 71.4e3);
        let stage_5 = deadband(v_in, 68e3, 33.0e3);
        let stage_45 = -33.0 / 71.4 * stage_4 - stage_5 - 33.0 / 240.0 * v_in;
        let sum = -150.0 / 100.0 * stage_1
            - 150.0 / 44.2 * stage_2
            - 150.0 / 18.0 * stage_3
            - 150.0 / 33.0 * stage_45;
        0.7 * sum / (0.3 + sum.abs())
    });
    let peak = raw.iter().fold(f64::MIN, |m, &v| m.max(v));
    raw.map(|v| v / peak)
}

/// The modulator ratios `harmonics` steps through: sub-octaves, simple
/// ratios, detuned copies of the sub-octave, unison and octave (beating
/// against the pure ratio), and a few inharmonic ones for bells.
///
/// The original detunes the unison and octave 16 cents sharp, after the
/// pure ratio, which puts the middle of `harmonics` on a detuned octave: a
/// sideband then sits 37 cents above the fundamental and outweighs it on
/// high notes, so the default voice sounds out of tune. Detuning those two
/// flat, before the pure ratio, keeps the same beating sounds and puts the
/// middle on a pure octave (odd harmonics, exactly in tune). The
/// sub-octave keeps its sharp copy, so the bottom stays a pure 0.5.
fn fm_ratio_list() -> [f64; 23] {
    use std::f64::consts::SQRT_2;
    let sharp = (16.0f64 / 1200.0).exp2();
    let flat = 1.0 / sharp;
    [
        0.5,
        0.5 * sharp,
        SQRT_2 / 2.0,
        PI / 4.0,
        flat,
        1.0,
        SQRT_2,
        PI / 2.0,
        7.0 / 4.0,
        2.0 * flat,
        2.0,
        9.0 / 4.0,
        11.0 / 4.0,
        2.0 * SQRT_2,
        3.0,
        PI,
        3.0f64.sqrt() * 2.0,
        4.0,
        SQRT_2 * 3.0,
        PI * 3.0 / 2.0,
        5.0,
        SQRT_2 * 4.0,
        8.0,
    ]
}

/// Each ratio as an interval, held for three steps, with the widest gaps
/// split until the table has [`RATIO_STEPS`] entries, then two guard
/// entries for interpolation.
fn fm_ratios() -> [f32; RATIO_STEPS + 2] {
    let mut scale = [0.0f64; RATIO_STEPS];
    let mut len = 0;
    for ratio in fm_ratio_list() {
        for _ in 0..3 {
            scale[len] = 12.0 * ratio.log2();
            len += 1;
        }
    }
    while len < RATIO_STEPS {
        // The first widest gap, as numpy's argmax picks it.
        let mut gap = 0;
        for i in 1..len - 1 {
            if scale[i + 1] - scale[i] > scale[gap + 1] - scale[gap] {
                gap = i;
            }
        }
        scale.copy_within(gap + 1..len, gap + 2);
        scale[gap + 1] = (scale[gap] + scale[gap + 2]) / 2.0;
        len += 1;
    }
    let mut table = [0.0; RATIO_STEPS + 2];
    for (entry, &v) in table.iter_mut().zip(scale.iter()) {
        *entry = v as f32;
    }
    table[RATIO_STEPS] = table[RATIO_STEPS - 1];
    table[RATIO_STEPS + 1] = table[RATIO_STEPS - 1];
    table
}

/// A Hermite-interpolated read of a wavefolder table at `index` (0..1
/// across its range). As in the original, the read lands one table step
/// (1/256 of the input) above `index`.
#[inline]
pub(super) fn hermite(table: &[f32; FOLD_SIZE], index: f32) -> f32 {
    let position = index.clamp(0.0, 0.999_999) * FOLD_STEPS as f32;
    let i = position as usize;
    let f = position - i as f32;
    // The table starts one entry before the range.
    let (xm1, x0, x1, x2) = (table[i], table[i + 1], table[i + 2], table[i + 3]);
    let c = (x1 - xm1) * 0.5;
    let v = x0 - x1;
    let w = c + v;
    let a = w + v + (x2 - x0) * 0.5;
    let b_neg = w + a;
    (((a * f) - b_neg) * f + c) * f + x0
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn shapers_are_odd_and_span_minus_one_to_one() {
        for (n, shaper) in tables().shapers.iter().enumerate() {
            assert!(shaper.iter().all(|v| v.is_finite()), "shaper {n}");
            assert!(shaper[SHAPER_HALF].abs() < 1e-6, "shaper {n}");
            for i in 0..=SHAPER_HALF {
                let (a, b) = (shaper[SHAPER_HALF + i], shaper[SHAPER_HALF - i]);
                assert!((a + b).abs() < 1e-6, "shaper {n} at {i}");
            }
        }
        // Linear is the identity.
        assert!((tables().shapers[2][SHAPER_SIZE - 1] - 1.0).abs() < 1e-6);
    }

    #[test]
    fn folds_are_normalised_and_odd() {
        let t = tables();
        for table in [&t.fold, &t.fold_2] {
            // Normalised by the highest value; the lowest may sit a hair
            // further out, as in the original.
            let high = table.iter().fold(f32::MIN, |m, &v| m.max(v));
            let low = table.iter().fold(f32::MAX, |m, &v| m.min(v));
            assert!((high - 1.0).abs() < 1e-6, "high {high}");
            assert!((-1.01..=-0.99).contains(&low), "low {low}");
            // Reads sit one step above the index (as in the original), so
            // an input of zero is one step below the middle.
            let zero = 0.5 - 1.0 / FOLD_STEPS as f32;
            assert!(hermite(table, zero).abs() < 1e-6);
            let (a, b) = (hermite(table, zero - 0.25), hermite(table, zero + 0.25));
            assert!((a + b).abs() < 1e-3, "{a} {b}");
        }
    }

    #[test]
    fn fm_ratios_rise_through_plateaus_from_an_octave_down_to_three_up() {
        let r = &tables().fm_ratios;
        assert!((r[0] + 12.0).abs() < 1e-5);
        assert!((r[RATIO_STEPS + 1] - 36.0).abs() < 1e-5);
        assert!(r.windows(2).all(|w| w[1] >= w[0]));
        // The middle sits on a plateau at a pure octave.
        let middle = &r[RATIO_STEPS / 2 - 1..=RATIO_STEPS / 2 + 1];
        assert!(middle.iter().all(|v| (v - 12.0).abs() < 1e-5), "{middle:?}");
        // π (for bells) holds a plateau further up.
        let pi = 12.0 * std::f32::consts::PI.log2();
        assert!(r[85..=87].iter().all(|v| (v - pi).abs() < 1e-4));
    }

    /// Spot values computed from the original Python formulas.
    #[test]
    fn tables_match_the_reference_formulas() {
        let t = tables();
        let close = |a: f32, b: f64| (f64::from(a) - b).abs() < 1e-5;
        assert!(close(t.shapers[3][SHAPER_HALF + 64], 0.758_714_1)); // bump(0.5)
        assert!(close(t.shapers[0][SHAPER_HALF + 32], 0.464_803_5)); // inverse_tan(0.25)
        assert!(close(t.fold[300], -0.502_949_7));
        assert!(close(t.fold[100], -0.827_300_4));
        assert!(close(t.fold_2[300], -0.658_519_4));
        assert!(close(t.fold_2[100], 0.566_553_9));
    }
}
